cd /workspace && python3 - <<'PY'
import json,sys
sys.path.insert(0,'/workspace/tmp/tests')
from ref import Image, Bad, Fib, norm
req=json.load(open('/tmp/failreq.json'))
case=req['cases'][0]
resp=json.loads(sys.popen if False else open('/dev/null').read() or '{}') if False else None
import subprocess
p=subprocess.run([sys.executable,'run.py'],input=json.dumps(req,separators=(',',':')).encode(),cwd='/workspace',capture_output=True)
res=json.loads(p.stdout.decode())['results'][0]
fib=Fib(); loaded=None; qi=0; snaps=[]; exp=[]
for op in case['ops']:
    if op[0]=='put': fib.put(op[1],op[2],op[3])
    elif op[0]=='save': snaps.append(res['snapshots'][len(snaps)])
    elif op[0]=='load_saved': loaded=Image(snaps[op[1]])
    elif op[0]=='load':
        try:
            loaded=Image(op[1])
        except Bad:
            pass
    elif op[0] in ('query','image_query'):
        for a in op[1]:
            exp.append(fib.lpm(a) if op[0]=='query' else (loaded.lookup(a) if loaded else None))
print('len exp',len(exp),'len got',len(res['answers']))
for i,(a,b) in enumerate(zip(exp,res['answers'])):
    if a!=b: print('first diff at',i,a,b); break
PY
